milestones.milestoneCriteriaFormula:
OR(AND(
        ISPICKVAL(Type, 'Standard'), 
        OR(
                Routing_Issue_Type__c == 'Non-Technical', 
                Routing_Issue_Type__c == 'Technical'
        ),
        ISPICKVAL(Contact.Active_services__c, 'Premium'), 
        OR(
                NOT(Contact.X24_7_Hand_off_Contact__c), 
                Contact.US_Support_required__c
        ),
        NOT(Contact.Premium_Support_Contact__c)
),

(AND(ISPICKVAL(Type, 'Escalation'),OR(Owner:Queue.QueueName =='SRE Escalations',Owner:User.UserRole.Name=='SRE Engineers')
)
)
)

OR(AND(
        ISPICKVAL(Type, 'Standard'), 
        OR(
                Routing_Issue_Type__c == 'Non-Technical', 
                Routing_Issue_Type__c == 'Technical'
        ),
        ISPICKVAL(Contact.Active_services__c, 'Premium'), 
        Contact.X24_7_Hand_off_Contact__c, 
        NOT(Contact.US_Support_required__c),
        NOT(Contact.Premium_Support_Contact__c)
),

(AND(ISPICKVAL(Type, 'Escalation'),OR(Owner:Queue.QueueName =='SRE Escalations',Owner:User.UserRole.Name=='SRE Engineers')
)
)
)

OR(AND(
ISPICKVAL(Type, 'Standard'),
OR(
Routing_Issue_Type__c == 'Non-Technical',
Routing_Issue_Type__c == 'Technical'
),
ISPICKVAL(Contact.Active_services__c, 'Premium'),
OR(
NOT(Contact.X24_7_Hand_off_Contact__c),
Contact.US_Support_required__c
),
Contact.Premium_Support_Contact__c
),

(AND(ISPICKVAL(Type, 'Escalation'),OR(Owner:Queue.QueueName =='SRE Escalations',Owner:User.UserRole.Name=='SRE Engineers')
)
)
)

OR(AND(
ISPICKVAL(Type, 'Standard'),
OR(
Routing_Issue_Type__c == 'Non-Technical',
Routing_Issue_Type__c == 'Technical'
),
ISPICKVAL(Contact.Active_services__c, 'Premium'),
Contact.X24_7_Hand_off_Contact__c,
NOT(Contact.US_Support_required__c),
Contact.Premium_Support_Contact__c
),

(AND(ISPICKVAL(Type, 'Escalation'),OR(Owner:Queue.QueueName =='SRE Escalations',Owner:User.UserRole.Name=='SRE Engineers')
)
)
)

OR(AND(
ISPICKVAL(Type, 'Standard'),
OR(
Routing_Issue_Type__c == 'Non-Technical',
Routing_Issue_Type__c == 'Technical'
),
ISPICKVAL(Contact.Active_services__c, 'Premium'),(Ispickval(Product_Account__r.Support_Tier__c ,"Advanced")),
OR(
NOT(Contact.X24_7_Hand_off_Contact__c),
Contact.US_Support_required__c
),
NOT(Contact.Premium_Support_Contact__c)
),

(AND(ISPICKVAL(Type, 'Escalation'),OR(Owner:Queue.QueueName =='SRE Escalations',Owner:User.UserRole.Name=='SRE Engineers')
)
)
)

OR(
    /* 1) Standard case with Advanced tier + flags */
    AND(
        ISPICKVAL(Type, "Standard"),
        ISPICKVAL(Product_Account__r.Support_Tier__c, "Advanced"),ISPICKVAL(Contact.Active_services__c, 'Premium'),
        Contact.X24_7_Hand_off_Contact__c,
        NOT(Contact.US_Support_required__c),
        NOT(Contact.Premium_Support_Contact__c)
    ),

    /* 2) Escalation case owned by SRE queue or SRE engineer */
    AND(
        ISPICKVAL(Type, "Escalation"),
        OR(
            Owner:Queue.QueueName = "SRE Escalations",
            Owner:User.UserRole.Name = "SRE Engineers"
        )
    )
)

OR(AND(
ISPICKVAL(Type, 'Standard'),
OR(
Routing_Issue_Type__c == 'Non-Technical',
Routing_Issue_Type__c == 'Technical'
),
ISPICKVAL(Contact.Active_services__c, 'Essential'),(Ispickval(Product_Account__r.Support_Tier__c ,"Advanced")),
OR(
NOT(Contact.X24_7_Hand_off_Contact__c),
Contact.US_Support_required__c
),
NOT(Contact.Premium_Support_Contact__c)
),

(AND(ISPICKVAL(Type, 'Escalation'),OR(Owner:Queue.QueueName =='SRE Escalations',Owner:User.UserRole.Name=='SRE Engineers')
)
)
)

OR(
/* 1) Standard case with Advanced tier + flags */
AND(
ISPICKVAL(Type, "Standard"),
ISPICKVAL(Product_Account__r.Support_Tier__c, "Advanced"),ISPICKVAL(Contact.Active_services__c, 'Essential'),
Contact.X24_7_Hand_off_Contact__c,
NOT(Contact.US_Support_required__c),
NOT(Contact.Premium_Support_Contact__c)
),

/* 2) Escalation case owned by SRE queue or SRE engineer */
AND(
ISPICKVAL(Type, "Escalation"),
OR(
Owner:Queue.QueueName = "SRE Escalations",
Owner:User.UserRole.Name = "SRE Engineers"
)
)
)

OR(
/* 1) Standard case with Advanced tier + flags */
AND(
ISPICKVAL(Type, "Standard"),
ISPICKVAL(Product_Account__r.Support_Tier__c, "Advanced"),ISPICKVAL(Contact.Active_services__c, ''),
Contact.X24_7_Hand_off_Contact__c,
NOT(Contact.US_Support_required__c),
NOT(Contact.Premium_Support_Contact__c)
),

/* 2) Escalation case owned by SRE queue or SRE engineer */
AND(
ISPICKVAL(Type, "Escalation"),
OR(
Owner:Queue.QueueName = "SRE Escalations",
Owner:User.UserRole.Name = "SRE Engineers"
)
)
)

OR(AND(
ISPICKVAL(Type, 'Standard'),
OR(
Routing_Issue_Type__c == 'Non-Technical',
Routing_Issue_Type__c == 'Technical'
),
ISPICKVAL(Contact.Active_services__c, ''),(Ispickval(Product_Account__r.Support_Tier__c ,"Advanced")),
OR(
NOT(Contact.X24_7_Hand_off_Contact__c),
Contact.US_Support_required__c
),
NOT(Contact.Premium_Support_Contact__c)
),

(AND(ISPICKVAL(Type, 'Escalation'),OR(Owner:Queue.QueueName =='SRE Escalations',Owner:User.UserRole.Name=='SRE Engineers')
)
)
)
